// Shared by the Linux Qt panel and the native Windows panel. UTF-8 throughout.
enum class UiLanguage { English=0, Portuguese=1, French=2, Spanish=3 };
inline constexpr std::array<std::string_view,4> uiLanguageCodes{"en","pt","fr","es"};
inline constexpr std::array<std::string_view,4> uiLanguageNames{"English","Português","Français","Español"};
inline constexpr std::string_view uiLanguageCode(UiLanguage language){
 const auto i=static_cast<unsigned>(language);return uiLanguageCodes[i<4?i:0];
}
inline constexpr UiLanguage uiLanguageFromCode(std::string_view code){
 for(unsigned i=0;i<4;++i)if(uiLanguageCodes[i]==code)return static_cast<UiLanguage>(i);return UiLanguage::English;
}
struct UiTranslation {std::string_view key;std::array<std::string_view,4> text;};
